package com.designly.project;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/projects") @CrossOrigin(origins="*") public class ProjectController{private final ProjectRepository repo;public ProjectController(ProjectRepository r){repo=r;}@GetMapping public List<DesignProject>all(){return repo.findAll();}@PostMapping public DesignProject create(@RequestBody DesignProject p){return repo.save(p);}@GetMapping("/{id}") public DesignProject get(@PathVariable Long id){return repo.findById(id).orElseThrow();}@PutMapping("/{id}") public DesignProject update(@PathVariable Long id,@RequestBody DesignProject p){DesignProject old=repo.findById(id).orElseThrow();old.setTitle(p.getTitle());old.setCategory(p.getCategory());old.setDesignJson(p.getDesignJson());return repo.save(old);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}